function CatalogPage({servicesOnly=false}){const {items,lang,t}=useShop();const [query,setQuery]=useState(''),[cat,setCat]=useState('all'),[sort,setSort]=useState('newest'),[type,setType]=useState('all');const displayed=useMemo(()=>items.filter(p=>p.active&&(!servicesOnly||p.kind==='Xizmat')&&(servicesOnly||type==='all'||(type==='product'?p.kind!=='Xizmat':p.kind===type))&&(cat==='all'||p.category===cat)&&[translatedTitle(lang,p),p.name,p.description,p.category,p.sellerName,p.institute].join(' ').toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())).sort((a,b)=>sort==='cheap'?a.price-b.price:sort==='expensive'?b.price-a.price:sort==='rating'?b.rating-a.rating:new Date(b.createdAt)-new Date(a.createdAt)),[items,servicesOnly,type,query,cat,sort,lang]);return <div className="shell page-space"><Heading eyebrow="SHODS SHOP" title={servicesOnly?t('services'):t('catalog')} detail={servicesOnly?t('aboutServices'):t('searchHelp')}/><div className="filters-panel"><div className="search-field"><Search size={19}/><input aria-label={t('search')} placeholder={t('search')} value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button onClick={()=>setQuery('')}><X size={16}/></button>}</div><select aria-label={t('category')} value={cat} onChange={e=>setCat(e.target.value)}><option value="all">{t('category')}: {t('all')}</option>{categories.map(c=><option key={c} value={c}>{translatedCategory(lang,c)}</option>)}</select>{!servicesOnly&&<select value={type} onChange={e=>setType(e.target.value)}><option value="all">{t('all')}</option><option value="product">{t('products')}</option><option value="Xizmat">{t('services')}</option></select>}<select aria-label={t('sort')} value={sort} onChange={e=>setSort(e.target.value)}>{['newest','cheap','expensive','rating'].map(s=><option key={s} value={s}>{t(s)}</option>)}</select></div><p className="count-note"><Filter size={15}/> {displayed.length} {t('listings')}</p><ItemsGrid list={displayed}/></div>}
function DetailPage(){const {t,lang,items,selectedId,go,addCart,user,reviews,setReviews,run,refresh}=useShop();const [stars,setStars]=useState(5),[review,setReview]=useState('');const item=items.find(i=>i.id===selectedId);useEffect(()=>{if(!selectedId)return;api('/reviews?itemId='+encodeURIComponent(selectedId)).then(r=>setReviews(r.reviews)).catch(()=>{})},[selectedId,setReviews]);if(!item)return <div className="shell page-space"><div className="empty-state">{t('notAvailable')}<button className="button primary" onClick={()=>go('catalog')}>{t('goCatalog')}</button></div></div>;const itemReviews=reviews.filter(r=>r.itemId===item.id);async function sendReview(e){e.preventDefault();await run(async()=>{await api('/reviews',{method:'POST',body:{itemId:item.id,stars,text:review}});setReview('');await refresh()},t('saved'))}
 return <div className="shell page-space"><button className="back-btn" onClick={()=>go('catalog')}><ArrowLeft size={16}/>{t('goBack')}</button><div className="detail-layout"><div><ImageFrame item={item} large/>{item.portfolio?.length>0&&<section className="surface spaced"><h3>{t('sellerPortfolio')}</h3><div className="portfolio-row">{item.portfolio.map((image,i)=><img alt={t('previousWorks')} src={image} key={i}/>)}</div></section>}</div><div className="surface detail-info"><span className="eyebrow-label">{translatedCategory(lang,item.category)}</span><h1>{translatedTitle(lang,item)}</h1><div className="rating-line"><Star size={18} fill="currentColor"/> {item.rating?item.rating.toFixed(1):'—'} <span>({item.reviewCount} {t('reviewTitle')})</span></div><div className="detail-price">{money(item.price,lang)}</div><p className="detail-description">{item.description}</p><div className="properties"><div><Package size={18}/>{t('kind')}<strong>{item.kind==='Xizmat'?t('service'):item.kind==='Raqamli'?t('digital'):t('physical')}</strong></div><div><Layers size={18}/>{t('stock')}<strong>{item.stock}</strong></div><div><GraduationCap size={18}/>{t('sellerInfo')}<strong>{item.sellerName}</strong></div><div><MapPin size={18}/>{t('address')}<strong>{item.location}</strong></div></div><div className="place-links"><a target="_blank" rel="noopener noreferrer" href={mapUrl(item)}><MapPin size={16}/>{t('getMap')} <ExternalLink size={13}/></a></div><button className="button primary large full" onClick={()=>addCart(item)}><ShoppingCart size={18}/>{t('addCart')}</button><p className="fine-print"><ShieldCheck size={14}/>{t('demoWarning')}</p><button className="seller-mini seller-link" onClick={()=>go('sellerPublic',item.seller)}><div className="avatar"><GraduationCap/></div><div><b>{item.sellerName}</b><small>{item.institute}</small><small>{item.faculty}</small><small className="click-seller">{t('viewSeller')} →</small></div></button></div></div>
 <section className="reviews-section"><Heading title={t('reviewTitle')}/><div className="review-grid"><div className="surface"><h3>{t('writeReview')}</h3><p className="small-muted">{t('reviewOnly')}</p><form onSubmit={sendReview}><div className="stars-picker">{[1,2,3,4,5].map(n=><button type="button" key={n} onClick={()=>setStars(n)} aria-label={`${n} ${t('stars')}`}><Star fill={n<=stars?'currentColor':'none'}/></button>)}</div><textarea required minLength={5} maxLength={600} placeholder={t('reviewText')} value={review} onChange={e=>setReview(e.target.value)}/><button className="button primary" disabled={!user}>{t('sendReview')}</button></form></div><div className="surface"><h3>{t('reviewTitle')} <span className="count-badge">{itemReviews.length}</span></h3>{itemReviews.length?itemReviews.map(r=><div className="review" key={r.id}><div><b>{r.buyerName}</b><span className="review-stars">{'★'.repeat(r.stars)}{'☆'.repeat(5-r.stars)}</span></div><p>{r.text}</p><small>{readable(r.createdAt,lang)}</small></div>):<p className="small-muted">{t('noReviews')}</p>}</div></div></section></div>}
function SellerPublicPage(){const {t,selectedId,lang}=useShop();const [data,setData]=useState(null);useEffect(()=>{if(selectedId)api('/sellers/'+encodeURIComponent(selectedId)).then(setData).catch(()=>setData({error:true}))},[selectedId]);if(!data)return <div className="shell page-space"><div className="loading-screen">{t('loading')}</div></div>;if(data.error)return <div className="shell page-space"><div className="empty-state">{t('notAvailable')}</div></div>;const total=data.reviews.reduce((sum,r)=>sum+r.stars,0),average=data.reviews.length?total/data.reviews.length:0;return <div className="shell page-space"><div className="surface public-seller"><div className="avatar seller-avatar"><GraduationCap size={33}/></div><div><span className="eyebrow-label">{t('viewSeller')}</span><h1>{data.seller.name}</h1><p><GraduationCap size={15}/>{data.seller.institute} • {data.seller.faculty}</p><p>{data.seller.direction} • {data.seller.course} {t('course')}</p></div><div className="seller-public-stats"><strong>{data.completed}</strong><small>{t('completedJobs')}</small><strong>{average?average.toFixed(1):'—'} ★</strong><small>{data.reviews.length} {t('reviewTitle')}</small></div></div><Heading title={t('sellerPortfolio')} detail={t('previousWorks')}/><ItemsGrid list={data.items}/><section className="surface"><h3>{t('reviewTitle')}</h3>{data.reviews.length?data.reviews.map(r=><div className="review" key={r.id}><div><b>{r.buyerName}</b><span className="review-stars">{'★'.repeat(r.stars)}</span></div><p>{r.text}</p><small>{readable(r.createdAt,lang)}</small></div>):<p className="small-muted">{t('noSellerReview')}</p>}</section></div>}
function CartPage(){const {t,items,lang,cart,setCart,go,user,run,refresh,toast}=useShop();const rows=cart.map(c=>({...items.find(x=>x.id===c.id),qty:c.qty})).filter(p=>p.id),total=rows.reduce((n,p)=>n+p.price*p.qty,0);const update=(id,delta)=>setCart(old=>old.map(c=>c.id===id?{...c,qty:Math.max(1,Math.min(items.find(x=>x.id===id)?.stock||1,c.qty+delta))}:c));async function checkout(){if(!user){toast(t('loginRequired'));return go('auth')}if(!window.confirm(t('confirmOrder')))return;await run(async()=>{await api('/orders',{method:'POST',body:{lines:rows.map(p=>({id:p.id,qty:p.qty})),payment:'demo'}});setCart([]);await refresh();go('buyer')},t('orderSuccess'))}
 return <div className="shell page-space"><Heading title={t('cart')} detail={t('basketCount')}/>{!rows.length?<div className="empty-state"><ShoppingCart size={42}/><h3>{t('cartEmpty')}</h3><button onClick={()=>go('catalog')} className="button primary">{t('continueShopping')}</button></div>:<div className="checkout-grid"><div className="surface">{rows.map(p=><div className="cart-row" key={p.id}><div className="cart-thumb"><ImageFrame item={p}/></div><div className="cart-item"><b>{translatedTitle(lang,p)}</b><small>{money(p.price,lang)}</small><span><MapPin size={12}/>{p.location}</span></div><div className="quantity"><button onClick={()=>update(p.id,-1)}><Minus size={15}/></button><b>{p.qty}</b><button onClick={()=>update(p.id,1)}><Plus size={15}/></button></div><button className="icon-btn danger" onClick={()=>setCart(c=>c.filter(x=>x.id!==p.id))}><Trash2 size={18}/></button></div>)}</div><div className="surface payment-box"><span className="eyebrow-label">{t('demoPayment')}</span><h3><Wallet size={22}/>{t('paymentMethod')}</h3><label className="payment-method"><input type="radio" defaultChecked name="payment"/><div><b>{t('demoCard')}</b><small>{t('paymentNote')}</small></div><CheckCircle2 size={20}/></label><div className="total-row"><span>{t('sum')}</span><b>{money(total,lang)}</b></div><button className="button primary full large" onClick={checkout}>{t('checkout')} <ArrowRight size={18}/></button><p className="fine-print"><ShieldCheck size={14}/>{t('demoWarning')}</p></div></div>}</div>}
function AuthPage(){const {t,config,go,login,register,lang,toast}=useShop();const [tab,setTab]=useState('login'),[form,setForm]=useState({name:'',login:'',password:'',institute:'Termiz davlat pedagogika instituti',faculty:'Tabiiy va aniq fanlar',direction:'Sun’iy intellekt',course:1}),[challenge,setChallenge]=useState(null),[verificationCode,setVerificationCode]=useState(''),[verified,setVerified]=useState(false),[busy,setBusy]=useState(false);useEffect(()=>{if(window.location.hash==='#register')setTab('register')},[]);
 const set=(k,v)=>setForm(old=>({...old,[k]:v}));
 async function submit(e){e.preventDefault();setBusy(true);try{if(tab==='login')await login({login:form.login,password:form.password});else await register({...form,telegramToken:challenge?.token})}finally{setBusy(false)}}
 async function startTelegram(){setBusy(true);try{const c=await api('/auth/telegram/start',{method:'POST',body:{}});setChallenge(c);setVerificationCode('');setVerified(false);window.open(c.url,'_blank','noopener,noreferrer')}catch(e){toast(cleanError(e,t))}finally{setBusy(false)}}
 async function checkTelegram(){if(!challenge||!/^\d{6}$/.test(verificationCode))return;try{const r=await api('/auth/telegram/confirm',{method:'POST',body:{token:challenge.token,code:verificationCode}});setVerified(r.verified);toast(r.verified?t('telegramVerified'):t('telegramNotVerified'))}catch(e){toast(cleanError(e,t))}}
 const field=(name,label,type='text')=><label className="field"><span>{label}</span><input type={type} value={form[name]} required minLength={name==='password'?8:undefined} onChange={e=>set(name,e.target.value)}/></label>;
 return <div className="shell page-space auth-page"><div className="auth-intro"><span className="round-icon"><GraduationCap size={28}/></span><h1>{tab==='login'?t('login'):t('createAccount')}</h1><p>{t('accountHelp')}</p><div className="auth-points"><span><ShieldCheck size={18}/>{t('roleDesc')}</span><span><MapPin size={18}/>{t('headerBadge')}</span><span><LockKeyhole size={18}/>{t('passwordNote')}</span></div></div><div className="surface auth-card"><div className="tab-strip"><button className={tab==='login'?'active':''} onClick={()=>setTab('login')}>{t('login')}</button><button className={tab==='register'?'active':''} onClick={()=>setTab('register')}>{t('register')}</button></div><form onSubmit={submit} className="form-stack">
 {tab==='register'&&<>{field('name',t('name'))}<label className="field"><span>{t('institute')}</span><select value={form.institute} required onChange={e=>set('institute',e.target.value)}>{(config.institutions||[]).map(x=><option key={x}>{x}</option>)}</select></label><label className="field"><span>{t('faculty')}</span><select value={form.faculty} required onChange={e=>set('faculty',e.target.value)}>{(config.faculties||[]).map(x=><option key={x}>{x}</option>)}</select></label><div className="field-split">{field('direction',t('direction'))}<label className="field"><span>{t('course')}</span><select value={form.course} onChange={e=>set('course',Number(e.target.value))}>{Array.from({length:6},(_,i)=><option key={i} value={i+1}>{i+1}</option>)}</select></label></div></>}
 {field('login',t('username'))}{field('password',t('password'),'password')}
 {tab==='register'&&(config.telegramEnabled?<div className="telegram-panel"><p><Send size={17}/>{t('telegramVerify')}</p><button className="button light" type="button" onClick={startTelegram}>{t('telegramOpen')} <ExternalLink size={14}/></button>{challenge&&<><label className="field"><span>{t('telegramOtpLabel')}</span><input type="text" inputMode="numeric" autoComplete="one-time-code" maxLength={6} placeholder="123456" value={verificationCode} onChange={e=>setVerificationCode(e.target.value.replace(/\D/g,'').slice(0,6))}/></label><button disabled={verificationCode.length!==6||verified} className="button outline" type="button" onClick={checkTelegram}>{t('telegramCheck')}</button></>}{verified&&<span className="success"><CheckCircle2 size={15}/>{t('telegramVerified')}</span>}</div>:<p className="info-note"><AlertCircle size={16}/>{t('registerNotice')}</p>)}
 <button disabled={busy||(tab==='register'&&config.telegramEnabled&&!verified)} className="button primary full large" type="submit">{busy?t('loading'):tab==='login'?t('login'):t('register')} <ArrowRight size={17}/></button></form>
 {tab==='login'&&<div className="demo-login"><p><b>{t('demoAccounts')}</b></p><p>{t('demoAccountsNote')} <code>ShodsDemo123!</code></p><div className="demo-login-btns"><button onClick={()=>{set('login','demo_s03');set('password','ShodsDemo123!')}}>{t('sellerDemo')}</button><button onClick={()=>{set('login','demo_x01');set('password','ShodsDemo123!')}}>{t('buyerDemo')}</button></div></div>}
 </div></div>}
function DashboardShell({children,role='buyer',active='overview',onNavigate}){const {t,user,go,mode,setMode}=useShop();const isSeller=role==='seller';const links=isSeller?[['seller','overview',LayoutDashboard,'sellerCab'],['seller','listings',Package,'myItems'],['seller','incoming',ClipboardList,'incoming'],['add','new',PlusCircle,'addListing']]:[['buyer','overview',LayoutDashboard,'buyerCab'],['buyer','orders',ClipboardList,'myOrders'],['buyer','favorites',Heart,'favorites'],['cart','cart',ShoppingCart,'cart']];return <div className="shell dashboard"><aside className="dash-aside"><div className="dashboard-user"><span className="avatar"><UserRound size={24}/></span><div><b>{user?.name}</b><small>{user?.faculty}</small></div></div><div className="sidebar-caption">{t('account')}</div>{links.map(([page,tab,Icon,label])=><button key={tab} className={active===tab?'current':''} onClick={()=>page==='seller'||page==='buyer'?onNavigate(tab):go(page)}><Icon size={18}/>{t(label)}</button>)}<div className="aside-bottom"><button onClick={()=>{setMode(isSeller?'buyer':'seller');go(isSeller?'buyer':'seller')}}><RefreshCcw size={16}/>{t('toggle')}</button></div></aside><section className="dash-body">{children}</section></div>}
function BuyerDashboard(){const {t,user,go,orders,favorites,items,lang}=useShop();const [tab,setTab]=useState('overview');const bought=orders.filter(o=>o.buyer===user.id);return <DashboardShell role="buyer" active={tab} onNavigate={setTab}><Heading eyebrow={t('goBuyer')} title={tab==='orders'?t('myOrders'):tab==='favorites'?t('favorites'):t('buyerCab')} detail={t('accountHelp')}/>{tab==='overview'&&<div className="stats-grid"><div className="stat-card"><span><ClipboardList/></span><small>{t('myOrders')}</small><strong>{bought.length}</strong></div><div className="stat-card"><span><Heart/></span><small>{t('favorites')}</small><strong>{favorites.length}</strong></div><div className="stat-card"><span><Package/></span><small>{t('listings')}</small><strong>{items.length}</strong></div></div>}
 {(tab==='overview'||tab==='orders')&&<section className="surface spaced"><div className="panel-header"><h3>{t('myOrders')}</h3><button className="text-button" onClick={()=>go('catalog')}>{t('goCatalog')} <ArrowRight size={14}/></button></div>{bought.length?<div className="data-list">{bought.map(o=><div className="order-row" key={o.id}><div className="row-icon"><Package/></div><div className="order-info"><b>{o.name}</b><small>#{o.id} • {readable(o.createdAt,lang)}</small><small><MapPin size={12}/>{o.location}</small></div><div className="order-meta"><b>{money(o.total,lang)}</b><small>{t('qty')}: {o.qty}</small><span className={'status status-'+o.status}>{t('status'+o.status.charAt(0).toUpperCase()+o.status.slice(1))}</span></div></div>)}</div>:<div className="empty-slim">{t('noOrders')}</div>}</section>}
 {tab==='favorites'&&<ItemsGrid list={items.filter(x=>favorites.includes(x.id))}/>}</DashboardShell>}
function SellerDashboard(){const {t,user,go,items,mine,refresh,run,orders,lang}=useShop();const [tab,setTab]=useState('overview');const sellers=orders.filter(o=>o.seller===user.id);const completed=sellers.filter(x=>x.status==='completed');async function status(o,next){await run(async()=>{await api('/orders/'+o.id,{method:'PATCH',body:{status:next}});await refresh()},t('saved'))}
 async function flipListing(item){await run(async()=>{await api('/listings/'+item.id,{method:'PATCH',body:{...item,active:!item.active}});await refresh()},t('saved'))}
 return <DashboardShell role="seller" active={tab} onNavigate={setTab}><Heading eyebrow={t('goSeller')} title={tab==='listings'?t('myItems'):tab==='incoming'?t('incoming'):t('sellerCab')} action={<button className="button primary" onClick={()=>go('add')}><Plus size={17}/>{t('addListing')}</button>}/>{tab==='overview'&&<div className="stats-grid"><div className="stat-card"><span><Package/></span><small>{t('myItems')}</small><strong>{mine.length}</strong></div><div className="stat-card"><span><ClipboardList/></span><small>{t('incoming')}</small><strong>{sellers.length}</strong></div><div className="stat-card"><span><CheckCircle2/></span><small>{t('completeOrder')}</small><strong>{completed.length}</strong></div></div>}
 {(tab==='overview'||tab==='listings')&&<section className="surface spaced"><div className="panel-header"><h3>{t('myItems')}</h3><button className="button outline small" onClick={()=>go('add')}><Plus size={16}/>{t('addListing')}</button></div>{mine.length?mine.map(item=><div className="listing-row" key={item.id}><div className="list-mini"><ImageFrame item={item}/></div><div className="list-info"><b>{translatedTitle(lang,item)}</b><small>{money(item.price,lang)} • {item.stock} {t('qty')}</small><span className={'status '+(item.active&&item.moderation!=='hidden'?'status-completed':'status-cancelled')}>{item.moderation==='hidden'?t('invisible'):item.active?t('active'):t('inactive')}</span></div><button className="button outline small" onClick={()=>go('add',item.id)}><Edit3 size={15}/>{t('edit')}</button><button disabled={item.moderation==='hidden'} className="button light small" onClick={()=>flipListing(item)}><Power size={15}/>{item.active?t('inactive'):t('active')}</button></div>):<div className="empty-slim">{t('noItems')}</div>}</section>}
 {(tab==='overview'||tab==='incoming')&&<section className="surface spaced"><div className="panel-header"><h3>{t('incoming')}</h3></div>{sellers.length?sellers.map(o=><div className="order-row" key={o.id}><div className="row-icon"><ShoppingBag/></div><div className="order-info"><b>{o.name}</b><small>{t('buyerCode')}: {o.buyerCode} • {readable(o.createdAt,lang)}</small><small>{t('qty')}: {o.qty} • {money(o.total,lang)}</small></div><div className="order-cta"><span className={'status status-'+o.status}>{t('status'+o.status.charAt(0).toUpperCase()+o.status.slice(1))}</span>{o.status==='new'&&<button className="button outline small" onClick={()=>status(o,'accepted')}>{t('accept')}</button>}{o.status==='accepted'&&<button className="button primary small" onClick={()=>status(o,'completed')}>{t('complete')}</button>}{['new','accepted'].includes(o.status)&&<button className="text-button warn" onClick={()=>status(o,'cancelled')}>{t('reject')}</button>}</div></div>):<div className="empty-slim">{t('noOrders')}</div>}</section>}</DashboardShell>}
const defaultListing={name:'',description:'',kind:'Moddiy',category:'Ta’lim',price:25000,stock:1,location:'Termiz shahri, institut hududi',active:true,image:null,imageHash:null,latitude:null,longitude:null,portfolio:[]};
function ListingEditor(){const {t,go,selectedId,mine,refresh,run,lang}=useShop();const existing=mine.find(x=>x.id===selectedId);const [form,setForm]=useState(()=>existing?{...defaultListing,...existing}:{...defaultListing});const [busy,setBusy]=useState(false);const [aiBusy,setAiBusy]=useState(false);const set=(k,v)=>setForm(f=>({...f,[k]:v}));
 useEffect(()=>{setForm(existing?{...defaultListing,...existing}:{...defaultListing})},[selectedId]);
 async function upload(e,portfolio=false){const files=Array.from(e.target.files||[]).slice(0,portfolio?3:1);if(!files.length)return;setBusy(true);try{const imageParts=await Promise.all(files.map(uploadListingPhoto));if(portfolio)setForm(old=>({...old,portfolio:[...(old.portfolio||[]),...imageParts.map(x=>x.image)].slice(0,3)}));else setForm(old=>({...old,...imageParts}))}catch(err){alert(err.message)}finally{setBusy(false);e.target.value=''}}
 function locate(){if(!navigator.geolocation)return alert('Geolocation unavailable');navigator.geolocation.getCurrentPosition(({coords})=>setForm(f=>({...f,latitude:coords.latitude,longitude:coords.longitude})),err=>alert(err.message),{enableHighAccuracy:false,timeout:9000})}
 async function suggestDesc(){if(!form.name)return;setAiBusy(true);try{const r=await api('/ai/assist',{method:'POST',body:{action:'description',title:form.name,category:form.category,lang}});set('description',r.description)}catch(e){alert(e.message)}finally{setAiBusy(false)}}
 async function save(e){e.preventDefault();setBusy(true);try{await run(async()=>{const [image,portfolio]=await Promise.all([compactOldPhoto(form.image),Promise.all((form.portfolio||[]).map(compactOldPhoto))]);const payload={...form,image,portfolio,price:Number(form.price),stock:Number(form.stock),latitude:form.latitude,longitude:form.longitude};if(new Blob([JSON.stringify(payload)]).size>1500000)throw Error('Rasmlar juda katta. Kamroq portfolio rasmi tanlang.');await api(existing?'/listings/'+existing.id:'/listings',{method:existing?'PATCH':'POST',body:payload});await refresh();go('seller')},t('listingCreated'))}finally{setBusy(false)}}
 return <div className="shell page-space"><button className="back-btn" onClick={()=>go('seller')}><ArrowLeft size={16}/>{t('goSeller')}</button><Heading title={existing?t('editListing'):t('addListing')} detail={t('sellProducts')}/><form onSubmit={save} className="listing-editor"><div className="surface"><div className="panel-header"><h3><Package size={20}/>{t('newListing')}</h3></div><div className="field-split"><label className="field"><span>{t('kind')}</span><select value={form.kind} onChange={e=>set('kind',e.target.value)}>{['Moddiy','Raqamli','Xizmat'].map(s=><option key={s} value={s}>{s==='Xizmat'?t('service'):s==='Raqamli'?t('digital'):t('physical')}</option>)}</select></label><label className="field"><span>{t('category')}</span><select value={form.category} onChange={e=>set('category',e.target.value)}>{categories.map(c=><option key={c} value={c}>{translatedCategory(lang,c)}</option>)}</select></label></div><label className="field"><span>{t('title')} *</span><input required maxLength={120} value={form.name} onChange={e=>set('name',e.target.value)} placeholder={t('title')}/></label><label className="field"><span className="label-actions">{t('description')} <button type="button" disabled={aiBusy} className="small-ai" onClick={suggestDesc}><Sparkles size={14}/>{t('aiDescription')}</button></span><textarea maxLength={1400} rows={5} value={form.description} onChange={e=>set('description',e.target.value)}/></label><div className="field-split"><label className="field"><span>{t('price')} ({t('priceUnit')})</span><input type="number" min={1} max={1000000000} required value={form.price} onChange={e=>set('price',e.target.value)}/></label><label className="field"><span>{t('stock')}</span><input type="number" min={1} max={100000} required value={form.stock} onChange={e=>set('stock',e.target.value)}/></label></div><label className="field"><span>{t('address')} *</span><input maxLength={200} required value={form.location} onChange={e=>set('location',e.target.value)} placeholder={t('locationHint')}/></label><button type="button" className="button light small" onClick={locate}><Navigation size={14}/>{t('shareLocation')}</button>{form.latitude!=null&&<div className="gps-note">GPS: {form.latitude.toFixed(5)}, {form.longitude.toFixed(5)} <button type="button" onClick={()=>setForm(f=>({...f,latitude:null,longitude:null}))}><X size={14}/></button></div>}<p className="fine-print"><AlertCircle size={14}/>{t('locationAlert')}</p><label className="toggle-line"><input type="checkbox" checked={!!form.active} onChange={e=>set('active',e.target.checked)}/><span>{t('active')} / {t('inactive')}</span><span className={'status '+(form.active?'status-completed':'status-cancelled')}>{form.active?t('active'):t('inactive')}</span></label></div>
 <div className="surface"><h3><ImagePlus size={20}/>{t('uploadPhotos')}</h3><label className="upload-area"><UploadCloud size={30}/><b>{t('photo')}</b><small>{t('photoHint')}</small><input type="file" accept="image/*" onChange={e=>upload(e)}/></label>{form.image&&<div className="image-preview"><img alt="Preview" src={form.image}/><button className="icon-btn" type="button" onClick={()=>setForm(f=>({...f,image:null,imageHash:null}))}><X size={18}/></button></div>}<h3 className="spaced">{t('portfolio')}</h3><p className="small-muted">{t('portfolioHelp')}</p><label className="upload-area compact"><ImagePlus size={20}/><span>{t('photo')}</span><input type="file" multiple accept="image/*" onChange={e=>upload(e,true)}/></label><div className="portfolio-row">{(form.portfolio||[]).map((img,i)=><div key={i}><img alt="Portfolio" src={img}/><button type="button" onClick={()=>set('portfolio',form.portfolio.filter((_,j)=>j!==i))}><X size={13}/></button></div>)}</div><button className="button primary full spaced large" disabled={busy} type="submit"><CheckCircle2 size={17}/>{existing?t('save'):t('create')}</button></div></form></div>}
function AIPage(){const {t,lang,go,run,user,config}=useShop();const [tab,setTab]=useState('finder'),[query,setQuery]=useState(''),[category,setCategory]=useState(categories[0]),[kind,setKind]=useState('Xizmat'),[title,setTitle]=useState(''),[scan,setScan]=useState(null),[result,setResult]=useState(null),[busy,setBusy]=useState(false);const tabs=[['finder',Search,'aiFinder'],['image',Camera,'aiImage'],['price',BarChart3,'aiPrice'],['description',FileText,'aiDescription']];async function imageUpload(e){try{const file=e.target.files?.[0];if(file){const data=await imageData(file);setScan(data);setResult(null)}}catch(e){alert(e.message)}}async function submit(e){e.preventDefault();if(!user)return go('auth');setBusy(true);try{let args={action:tab,lang};if(tab==='finder')args.query=query;else if(tab==='image')args={...args,...scan};else if(tab==='price')args={...args,kind,category};else args={...args,title,category};const res=await api('/ai/assist',{method:'POST',body:args});setResult(res)}catch(e){alert(cleanError(e,t))}finally{setBusy(false)}}
 return <div className="shell page-space"><div className="ai-header"><div className="sparkle-circle"><Sparkles size={30}/></div><div><span className="eyebrow-label">SHODS AI</span><h1>{t('aiTitle')}</h1><p>{t('aiSubtitle')}</p></div><span className="ai-badge"><span className="online-dot"/>{config.aiEnabled?t('aiModelOn'):t('aiModelOff')}</span></div><div className="ai-tabs">{tabs.map(([k,Icon,label])=><button key={k} className={tab===k?'active':''} onClick={()=>{setTab(k);setResult(null)}}><Icon size={19}/>{t(label)}</button>)}</div><div className="ai-main"><form onSubmit={submit} className="surface ai-form"><h2>{t(tabs.find(a=>a[0]===tab)[2])}</h2>{tab==='finder'&&<><p>{t('provider')}</p><label className="field"><span>{t('search')}</span><textarea value={query} required placeholder={t('aiQuery')} onChange={e=>setQuery(e.target.value)}/></label></>}{tab==='image'&&<><p>{t('aiHint')}</p><label className="upload-area"><Camera size={30}/><b>{t('photoScan')}</b><input accept="image/png,image/jpeg,image/webp" type="file" onChange={imageUpload}/></label>{scan?.image&&<img className="scan-photo" src={scan.image} alt="Scan"/>}</>}{tab==='price'&&<><label className="field"><span>{t('kind')}</span><select value={kind} onChange={e=>setKind(e.target.value)}><option value="Xizmat">{t('service')}</option><option value="Moddiy">{t('physical')}</option><option value="Raqamli">{t('digital')}</option></select></label><label className="field"><span>{t('category')}</span><select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c} value={c}>{translatedCategory(lang,c)}</option>)}</select></label></>}{tab==='description'&&<><label className="field"><span>{t('title')}</span><input value={title} required onChange={e=>setTitle(e.target.value)}/></label><label className="field"><span>{t('category')}</span><select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c} value={c}>{translatedCategory(lang,c)}</option>)}</select></label></>}<button disabled={busy||(tab==='image'&&!scan)} className="button primary full large"><Sparkles size={18}/>{busy?t('loading'):tab==='image'?t('scan'):tab==='finder'?t('find'):tab==='price'?t('suggest'):t('generate')}</button><p className="fine-print"><ShieldCheck size={14}/>{t('aiCaution')}</p></form><div className="surface ai-result"><h3><Sparkles size={20}/>{t('aiSearchResults')}</h3>{!result?<div className="ai-placeholder"><div>✦</div><p>{t('aiSubtitle')}</p></div>:<div className="ai-content"><span className="small-muted">{t('aiSource')}: {result.engine}</span>{tab==='finder'&&(result.results?.length?<div className="ai-match-list">{result.results.map(p=><button key={p.id} onClick={()=>go('detail',p.id)}><span>{p.emoji||'📦'}</span><div><b>{translatedTitle(lang,p)}</b><small>{p.sellerName} • {money(p.price,lang)}</small></div><ArrowRight size={16}/></button>)}</div>:<p>{t('noComparison')}</p>)}{tab==='image'&&<><p className="small-muted">{result.description||result.warning}</p>{(result.matches||result.visualMatches||[]).length?<div className="ai-match-list">{(result.matches?.length?result.matches:result.visualMatches).map(p=><button key={p.id} onClick={()=>go('detail',p.id)}><span>{p.emoji||'📦'}</span><div><b>{translatedTitle(lang,p)}</b><small>{money(p.price,lang)} {p.similarity?`• ${p.similarity}%`:''}</small></div><ArrowRight size={16}/></button>)}</div>:<p>{t('aiNothing')}</p>}{result.category&&<p>{t('category')}: <b>{result.category}</b></p>}</>}{tab==='price'&&(result.median?<><p>{t('median')}: <strong>{money(result.median,lang)}</strong></p><h2>{result.range.map(v=>money(v,lang)).join(' – ')}</h2><p className="small-muted">{result.note}</p></>:<p>{t('noComparison')}</p>)}{tab==='description'&&<><div className="ai-generated">{result.description}</div><button className="button outline small" onClick={()=>navigator.clipboard?.writeText(result.description)}><Copy size={15}/>{t('copied')}</button></>}</div>}</div></div></div>}
function SupportPage(){const {t,user,go,tickets,refresh,run,lang}=useShop();const [topic,setTopic]=useState('Account'),[message,setMessage]=useState('');async function send(e){e.preventDefault();if(!user)return go('auth');await run(async()=>{await api('/support',{method:'POST',body:{topic,message}});setMessage('');await refresh()},t('requestSaved'))}const faqs=[['faq1','faqA1'],['faq2','faqA2'],['faq3','faqA3']];return <div className="shell page-space"><Heading eyebrow="SHODS HELP" title={t('supportTitle')} detail={t('supportHint')}/><div className="support-grid"><div className="surface"><h3><LifeBuoy size={20}/>{t('faq')}</h3><div className="faq-list">{faqs.map(([q,a])=><details key={q}><summary>{t(q)}</summary><p>{t(a)}</p></details>)}</div><h3 className="spaced">{t('myTickets')}</h3>{user&&tickets.length?tickets.map(x=><div className="ticket" key={x.id}><b>{x.topic}</b><span className={'status status-'+(x.status==='closed'?'completed':'new')}>{x.status}</span><p>{x.message}</p><small>{readable(x.createdAt,lang)}</small>{x.reply&&<div className="ticket-reply"><b>{t('replyFromAdmin')}</b><p>{x.reply}</p></div>}</div>):<p className="small-muted">{t('empty')}</p>}</div><form className="surface" onSubmit={send}><h3><MessageCircle size={20}/>{t('newSupport')}</h3><label className="field"><span>{t('topic')}</span><select value={topic} onChange={e=>setTopic(e.target.value)}>{[['Account','problemAccount'],['Order','problemOrder'],['Listing','problemListing'],['Complaint','problemComplaint'],['Technical','problemTech']].map(([v,l])=><option key={v} value={v}>{t(l)}</option>)}</select></label><label className="field"><span>{t('message')}</span><textarea minLength={10} maxLength={1500} required rows={8} value={message} onChange={e=>setMessage(e.target.value)}/></label><button className="button primary full" type="submit"><Send size={16}/>{t('send')}</button><p className="small-muted">{t('supportHint')}</p></form></div></div>}
function AdminPage(){const {t,user,run,lang,toast,refresh}=useShop();const [tab,setTab]=useState('overview'),[data,setData]=useState({}),[loading,setLoading]=useState(false),[reply,setReply]=useState({});const tabs=[['overview',LayoutDashboard,'overview'],['users',Users,'users'],['listings',Package,'moderation'],['orders',ClipboardList,'adminOrders'],['tickets',MessageCircle,'tickets'],['reviews',Star,'adminReviews'],['audit',History,'audit']];async function load(name){setLoading(true);try{const endpoint={overview:'overview',users:'users',listings:'listings',orders:'orders',tickets:'tickets',reviews:'reviews',audit:'audit'}[name];const result=await api('/admin/'+endpoint);setData(prev=>({...prev,[name]:result}))}catch(e){toast(cleanError(e,t))}finally{setLoading(false)}}useEffect(()=>{if(user?.role==='admin')load(tab)},[tab,user?.role]);if(user?.role!=='admin')return <div className="shell page-space"><div className="empty-state"><LockKeyhole size={33}/><h3>{t('accessDenied')}</h3></div></div>;
 const change=async(url,payload,method='PATCH')=>run(async()=>{await api(url,{method,body:payload});await load(tab);await refresh()},t('adminSuccess'));
 async function exportData(){try{const r=await api('/admin/export');const blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`SHODS_ADMIN_REPORT_${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url)}catch(e){toast(cleanError(e,t))}}
 const rows=data[tab]||{};
 return <div className="shell page-space admin-page"><div className="admin-hero"><div className="admin-symbol"><ShieldCheck size={27}/></div><div><span className="eyebrow-label">SHODS SHOP</span><h1>{t('admin')}</h1><p>{t('adminSecure')}</p></div><button className="button outline" onClick={exportData}><Download size={16}/>{t('backup')}</button></div><div className="admin-layout"><aside className="surface admin-menu"><span className="sidebar-caption">{t('admin')}</span>{tabs.map(([key,Icon,label])=><button key={key} className={tab===key?'current':''} onClick={()=>setTab(key)}><Icon size={18}/>{t(label)}</button>)}</aside><div className="admin-content"><div className="panel-header"><h2>{t(tabs.find(x=>x[0]===tab)?.[2]||tab)}</h2><button className="button outline small" onClick={()=>load(tab)}><RefreshCcw size={15}/>{t('reload')}</button></div>{loading&&<div className="loading-line"/>}
 {tab==='overview'&&<><div className="stats-grid admin-stats">{[['users',Users,'usersCount'],['listings',Package,'listingsCount'],['orders',ClipboardList,'ordersCount'],['demoTurnover',Wallet,'demoSum'],['ticketsOpen',MessageCircle,'openTickets'],['reviews',Star,'adminReviews']].map(([id,Icon,label])=><div className="stat-card" key={id}><span><Icon/></span><small>{t(label)}</small><strong>{id==='demoTurnover'?money(rows.stats?.[id],lang):rows.stats?.[id]??0}</strong></div>)}</div><section className="surface spaced"><h3>{t('lastActivity')}</h3><div className="admin-table-wrap"><table><thead><tr><th>ID</th><th>{t('title')}</th><th>{t('price')}</th><th>{t('status')}</th></tr></thead><tbody>{rows.recentOrders?.map(o=><tr key={o.id}><td>{o.id.slice(0,12)}</td><td>{o.name}</td><td>{money(o.total,lang)}</td><td>{o.status}</td></tr>)}</tbody></table></div></section></>}
 {tab==='users'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('name')}</th><th>{t('username')}</th><th>{t('institute')}</th><th>{t('accountStatus')}</th><th>{t('actions')}</th></tr></thead><tbody>{rows.users?.map(u=><tr key={u.id}><td><b>{u.name}</b>{u.role==='admin'&&<span className="role-chip">ADMIN</span>}</td><td>{u.login}</td><td>{u.institute}</td><td><span className={'status '+(u.status==='suspended'?'status-cancelled':'status-completed')}>{u.status}</span></td><td>{u.role!=='admin'?<button className={'button small '+(u.status==='suspended'?'outline':'light')} onClick={()=>change('/admin/users/'+u.id,{status:u.status==='suspended'?'active':'suspended'})}>{u.status==='suspended'?t('unblock'):t('block')}</button>:'—'}</td></tr>)}</tbody></table></div>}
 {tab==='listings'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('title')}</th><th>{t('seller')}</th><th>{t('price')}</th><th>{t('status')}</th><th>{t('actions')}</th></tr></thead><tbody>{rows.items?.map(p=><tr key={p.id}><td><b>{translatedTitle(lang,p)}</b><small>{translatedCategory(lang,p.category)}</small></td><td>{p.sellerName}</td><td>{money(p.price,lang)}</td><td><span className={'status '+(p.moderation==='hidden'?'status-cancelled':'status-completed')}>{p.moderation==='hidden'?t('invisible'):t('visible')}</span></td><td><button className="button light small" onClick={()=>change('/admin/listings/'+p.id,{moderation:p.moderation==='hidden'?'approved':'hidden'})}>{p.moderation==='hidden'?t('restore'):t('hide')}</button></td></tr>)}</tbody></table></div>}
 {tab==='orders'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('title')}</th><th>{t('buyer')}</th><th>{t('seller')}</th><th>{t('sum')}</th><th>{t('status')}</th></tr></thead><tbody>{rows.orders?.map(o=><tr key={o.id}><td><b>{o.name}</b><small>#{o.id.slice(0,14)}</small></td><td>{o.buyerName}</td><td>{o.sellerName}</td><td>{money(o.total,lang)}</td><td>{o.status}</td></tr>)}</tbody></table></div>}
 {tab==='tickets'&&<div className="admin-tickets">{rows.tickets?.length?rows.tickets.map(ticket=><div className="surface" key={ticket.id}><div className="panel-header"><h3>{ticket.topic}</h3><span className={'status '+(ticket.status==='closed'?'status-completed':'status-new')}>{ticket.status}</span></div><small>{ticket.userName} • {readable(ticket.createdAt,lang)}</small><p>{ticket.message}</p><label className="field"><span>{t('answer')}</span><textarea rows={3} value={reply[ticket.id]??ticket.reply??''} onChange={e=>setReply(s=>({...s,[ticket.id]:e.target.value}))}/></label><div className="admin-buttons"><button className="button primary small" onClick={()=>change('/admin/tickets/'+ticket.id,{status:'answered',reply:reply[ticket.id]??ticket.reply??''})}>{t('sendAnswer')}</button><button className="button light small" onClick={()=>change('/admin/tickets/'+ticket.id,{status:'closed',reply:reply[ticket.id]??ticket.reply??''})}>{t('closeTicket')}</button></div></div>):<div className="empty-slim">{t('empty')}</div>}</div>}
 {tab==='reviews'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('buyer')}</th><th>{t('title')}</th><th>{t('stars')}</th><th>{t('reviewText')}</th><th>{t('actions')}</th></tr></thead><tbody>{rows.reviews?.map(r=><tr key={r.id}><td>{r.buyerName}</td><td>{r.itemId}</td><td>{'★'.repeat(r.stars)}</td><td>{r.text}</td><td><button className="button light small" onClick={()=>{if(window.confirm(t('removeReview')+'?'))change('/admin/reviews/'+r.id,undefined,'DELETE')}}><Trash2 size={14}/>{t('removeReview')}</button></td></tr>)}</tbody></table></div>}
 {tab==='audit'&&<div className="surface admin-table-wrap"><table><thead><tr><th>{t('createdAt')}</th><th>{t('admin')}</th><th>{t('actions')}</th><th>{t('title')}</th></tr></thead><tbody>{rows.audit?.map(r=><tr key={r.id}><td>{readable(r.at,lang)}</td><td>{r.adminName}</td><td>{r.action}</td><td>{r.target}</td></tr>)}</tbody></table></div>}
 </div></div></div>}
function MobileBar(){const {t,go,page,user,cart}=useShop();const items=[['home',Home,'home'],['catalog',Search,'catalog'],['cart',ShoppingCart,'cart'],[user?'buyer':'auth',UserRound,user?'profile':'login']];return <div className="mobile-bar">{items.map(([path,Icon,label])=><button key={path} className={page===path?'current':''} onClick={()=>go(path)}><Icon size={21}/><small>{t(label)}</small></button>)}</div>}
export default function App(){
 const [lang,setLang]=useState(()=>localStorage.getItem('shods_lang')||'uz');
 const [theme,setTheme]=useState(()=>localStorage.getItem('shods_theme')||'light');
 const [page,setPage]=useState('home');const [selectedId,setSelectedId]=useState(null);
 const [mode,setMode]=useState(()=>localStorage.getItem('shods_mode')||'buyer');
 const [installPrompt,setInstallPrompt]=useState(null);
 const [items,setItems]=useState([]),[mine,setMine]=useState([]),[orders,setOrders]=useState([]),[reviews,setReviews]=useState([]),[tickets,setTickets]=useState([]),[favorites,setFavorites]=useState([]),[user,setUser]=useState(null),[cart,setCart]=useState(()=>{try{return JSON.parse(localStorage.getItem('shods_cart')||'[]')}catch{return []}}),[config,setConfig]=useState({institutions:[],faculties:[]}),[loading,setLoading]=useState(true),[notice,setNotice]=useState(''),[mobileMenu,setMobileMenu]=useState(false);
 const t=key=>tLang(lang,key);
 useEffect(()=>{const h=e=>{e.preventDefault();setInstallPrompt(e)};window.addEventListener('beforeinstallprompt',h);return ()=>window.removeEventListener('beforeinstallprompt',h)},[]);
 async function install(){if(!installPrompt)return;await installPrompt.prompt();setInstallPrompt(null)}
 useEffect(()=>{localStorage.setItem('shods_lang',lang);document.documentElement.lang=lang},[lang]);useEffect(()=>{localStorage.setItem('shods_theme',theme);document.documentElement.dataset.theme=theme},[theme]);useEffect(()=>{localStorage.setItem('shods_mode',mode)},[mode]);useEffect(()=>{localStorage.setItem('shods_cart',JSON.stringify(cart))},[cart]);
 function toast(message){setNotice(message);window.clearTimeout(window.__shodsToast);window.__shodsToast=setTimeout(()=>setNotice(''),4300)}
 function go(next,id){if(['seller','buyer','add','admin'].includes(next)&&!user){setPage('auth');return}if(next==='admin'&&user?.role!=='admin')return toast(t('accessDenied'));if(next==='seller'||next==='add')setMode('seller');if(next==='buyer')setMode('buyer');setPage(next);setSelectedId(id||null);setMobileMenu(false);if(next==='auth'&&id==='register')window.location.hash='register';else if(window.location.hash)history.replaceState(null,'',location.pathname);window.scrollTo({top:0,behavior:'instant'})}
 async function refresh(){const initial=await api('/bootstrap');setItems(initial.items);setConfig({...initial.config,institutions:initial.institutions,faculties:initial.faculties});const auth=await api('/auth/me');setUser(auth.user);if(auth.user){const [my,orderData,ticketData,fav]=await Promise.all([api('/listings/mine'),api('/orders?type=both'),api('/support'),api('/favorites')]);setMine(my.items);setOrders(orderData.orders);setTickets(ticketData.tickets);setFavorites(fav.ids)}else{setMine([]);setOrders([]);setTickets([]);setFavorites([])}return auth.user}
 useEffect(()=>{refresh().catch(e=>toast(t('errorNetwork'))).finally(()=>setLoading(false))},[]);
 async function run(fn,message){try{const result=await fn();if(message)toast(message);return result}catch(e){toast(cleanError(e,t));return null}}
 async function login(payload){const result=await run(async()=>{await api('/auth/login',{method:'POST',body:payload});await refresh();setPage('buyer');window.scrollTo(0,0)},t('ok'));return result}
 async function register(payload){return run(async()=>{await api('/auth/register',{method:'POST',body:payload});await refresh();setPage('buyer');window.scrollTo(0,0)},t('saved'))}
 async function logout(){await run(async()=>{await api('/auth/logout',{method:'POST',body:{}});await refresh();setCart([]);go('home')},t('logout'))}
 function addCart(item){if(!user){go('auth');return toast(t('loginRequired'))}if(item.seller===user.id)return toast(t('ownItem'));if(item.stock<=0||!item.active)return toast(t('unavailable'));setCart(old=>{const found=old.find(o=>o.id===item.id);return found?old.map(x=>x.id===item.id?{...x,qty:Math.min(item.stock,x.qty+1)}:x):[...old,{id:item.id,qty:1}]});toast(t('addCart'))}
 async function toggleFavorite(id){if(!user)return go('auth');await run(async()=>{const r=await api('/favorites/'+id,{method:'POST',body:{}});setFavorites(r.ids)},t('saved'))}
 const context={t,lang,setLang,theme,setTheme,installPrompt,install,page,go,selectedId,items,mine,orders,reviews,setReviews,tickets,favorites,cart,setCart,user,mode,setMode,mobileMenu,setMobileMenu,config,loading,toast,refresh,run,login,register,logout,addCart,toggleFavorite};
 return <ShopContext.Provider value={context}><div className="app"><Header/>{loading?<div className="shell page-space"><div className="loading-screen"><Sparkles size={34}/><p>{t('dataLoading')}</p></div></div>:<>{page==='home'&&<HomePage/>}{page==='catalog'&&<CatalogPage/>}{page==='services'&&<CatalogPage servicesOnly/>}{page==='detail'&&<DetailPage/>}{page==='sellerPublic'&&<SellerPublicPage/>}{page==='cart'&&<CartPage/>}{page==='auth'&&<AuthPage/>}{page==='buyer'&&(user?<BuyerDashboard/>:<AuthPage/>)}{page==='seller'&&(user?<SellerDashboard/>:<AuthPage/>)}{page==='add'&&(user?<ListingEditor/>:<AuthPage/>)}{page==='ai'&&<AIPage/>}{page==='support'&&<SupportPage/>}{page==='admin'&&<AdminPage/>}</>}<Footer/><MobileBar/>{notice&&<div role="status" className="toast"><CheckCircle2 size={20}/><span>{notice}</span><button onClick={()=>setNotice('')}><X size={16}/></button></div>}</div></ShopContext.Provider>
}
